 17	constexpr int8_t kRefBase = 0;       // DR_BASE: 베이스 좌표계
 18	constexpr int8_t kModeAbsolute = 0;  // 절대 좌표 목표
 19	constexpr int8_t kSyncAsync = 1;     // 명령만 넣고 바로 돌아옴
