 24	RobotClient::RobotClient(rclcpp::Node * node, rclcpp::CallbackGroup::SharedPtr group, Options options)
 25	: node_(node), opt_(std::move(options))
 26	{
 27	  const std::string p = opt_.ns;
 28	  const auto qos = rclcpp::ServicesQoS();
 29	  move_joint_ = node_->create_client<MoveJoint>(p + "/motion/move_joint", qos, group);
 30	  move_line_ = node_->create_client<MoveLine>(p + "/motion/move_line", qos, group);
 31	  move_stop_ = node_->create_client<MoveStop>(p + "/motion/move_stop", qos, group);
 32	  check_motion_ = node_->create_client<CheckMotion>(p + "/motion/check_motion", qos, group);
 33	  ikin_ = node_->create_client<Ikin>(p + "/motion/ikin", qos, group);
 34	  fkin_ = node_->create_client<Fkin>(p + "/motion/fkin", qos, group);
 35	  get_posx_ = node_->create_client<GetCurrentPosx>(p + "/aux_control/get_current_posx", qos, group);
 36	  get_state_ = node_->create_client<GetRobotState>(p + "/system/get_robot_state", qos, group);
 37	}
