 39	bool RobotClient::servicesReady(std::string * missing) const
 40	{
 41	  const std::vector<rclcpp::ClientBase *> all{move_joint_.get(), move_line_.get(), move_stop_.get(),
 42	    check_motion_.get(), ikin_.get(), fkin_.get(), get_posx_.get(), get_state_.get()};
 43	  for (auto * c : all) {
 44	    if (!c->service_is_ready()) {
 45	      if (missing) {*missing = c->get_service_name();}
 46	      return false;
 47	    }
 48	  }
 49	  return true;
 50	}
