 52	int RobotClient::robotState()
 53	{
 54	  auto res = callService<GetRobotState>(get_state_, std::make_shared<GetRobotState::Request>(),
 55	      opt_.service_timeout_s);
 56	  return (res && res->success) ? res->robot_state : -1;
 57	}
