 59	std::optional<std::array<double, 6>> RobotClient::currentPose()
 60	{
 61	  auto req = std::make_shared<GetCurrentPosx::Request>();
 62	  req->ref = kRefBase;
 63	  auto res = callService<GetCurrentPosx>(get_posx_, req, opt_.service_timeout_s);
 64	  if (!res || !res->success || res->task_pos_info.empty() || res->task_pos_info[0].data.size() < 6) {
 65	    return std::nullopt;
 66	  }
 67	  std::array<double, 6> out{};
 68	  for (int i = 0; i < 6; ++i) {out[i] = res->task_pos_info[0].data[i];}
 69	  return out;
 70	}
