 72	bool RobotClient::stop()
 73	{
 74	  auto req = std::make_shared<MoveStop::Request>();
 75	  req->stop_mode = kStopQuick;
 76	  auto res = callService<MoveStop>(move_stop_, req, opt_.service_timeout_s);
 77	  return res && res->success;
 78	}
