113	void RobotClient::moveJoints(const std::array<double, 6> & deg, const std::string & label, const AbortCheck & abort)
114	{
115	  auto req = std::make_shared<MoveJoint::Request>();
116	  for (int i = 0; i < 6; ++i) {req->pos[i] = deg[i];}
117	  req->vel = opt_.joint_vel_deg_s;
118	  req->acc = opt_.joint_acc_deg_s2;
119	  req->mode = kModeAbsolute;
120	  req->sync_type = kSyncAsync;
121	  auto res = callService<MoveJoint>(move_joint_, req, opt_.service_timeout_s);
122	  if (!res || !res->success) {
123	    throw TaskError(ErrorCode::MOTION_FAILED, label + ": move_joint 거부됨");
124	  }
125	  waitForMotion(label, abort);
126	  // 도착 확인: 관절각 대신 플랜지 자세를 FK 로 비교하면 단순해지지만, 관절 목표는 관절로 확인하는 것이 정확하다.
127	  // 두산 get_current_posj 를 쓰지 않고, 목표 관절각의 FK 와 현재 플랜지 위치를 비교한다(서비스 수를 줄이기 위해).
128	  auto fk_req = std::make_shared<Fkin::Request>();
129	  for (int i = 0; i < 6; ++i) {fk_req->pos[i] = deg[i];}
130	  fk_req->ref = kRefBase;
131	  auto fk = callService<Fkin>(fkin_, fk_req, opt_.service_timeout_s);
132	  auto now = currentPose();
133	  if (!fk || !now) {
134	    throw TaskError(ErrorCode::MOTION_FAILED, label + ": 도착 확인 실패 (fkin/현재 위치 응답 없음)");
135	  }
136	  const Vec3 d{now->at(0) - fk->conv_posx[0], now->at(1) - fk->conv_posx[1], now->at(2) - fk->conv_posx[2]};
137	  if (norm(d) > opt_.arrival_tolerance_mm) {
138	    char buf[160];
139	    std::snprintf(buf, sizeof(buf), "%s: 목표 자세에 도착하지 못함 (플랜지 위치 차이 %.1f mm)", label.c_str(), norm(d));
140	    throw TaskError(ErrorCode::MOTION_FAILED, buf);
141	  }
142	}
