144	void RobotClient::moveLinear(const std::array<double, 6> & pose, const std::string & label, const AbortCheck & abort)
145	{
146	  auto req = std::make_shared<MoveLine::Request>();
147	  for (int i = 0; i < 6; ++i) {req->pos[i] = pose[i];}
148	  req->vel = {opt_.linear_vel_mm_s, 60.0};    // [직선 mm/s, 회전 deg/s]
149	  req->acc = {opt_.linear_acc_mm_s2, 120.0};
150	  req->ref = kRefBase;
151	  req->mode = kModeAbsolute;
152	  req->sync_type = kSyncAsync;
153	  auto res = callService<MoveLine>(move_line_, req, opt_.service_timeout_s);
154	  if (!res || !res->success) {
155	    throw TaskError(ErrorCode::MOTION_FAILED, label + ": move_line 거부됨");
156	  }
157	  waitForMotion(label, abort);
158	  auto now = currentPose();
159	  if (!now) {
160	    throw TaskError(ErrorCode::MOTION_FAILED, label + ": 도착 확인 실패 (현재 위치 응답 없음)");
161	  }
162	  const Vec3 d{now->at(0) - pose[0], now->at(1) - pose[1], now->at(2) - pose[2]};
163	  if (norm(d) > opt_.arrival_tolerance_mm) {
164	    char buf[200];
165	    std::snprintf(buf, sizeof(buf), "%s: 목표에 도착하지 못함 (남은 거리 %.1f mm, 도달 불가 위치일 수 있음)",
166	      label.c_str(), norm(d));
167	    throw TaskError(ErrorCode::MOTION_FAILED, buf);
168	  }
169	}
