171	double RobotClient::reachabilityErrorMm(const std::array<double, 6> & pose)
172	{
173	  auto ik_req = std::make_shared<Ikin::Request>();
174	  for (int i = 0; i < 6; ++i) {ik_req->pos[i] = pose[i];}
175	  ik_req->sol_space = 2;  // 팔꿈치 위 자세 계열 (홈 자세와 같은 계열)
176	  ik_req->ref = kRefBase;
177	  auto ik = callService<Ikin>(ikin_, ik_req, opt_.service_timeout_s);
178	  if (!ik || !ik->success) {return -1.0;}
179	  auto fk_req = std::make_shared<Fkin::Request>();
180	  fk_req->pos = ik->conv_posj;
181	  fk_req->ref = kRefBase;
182	  auto fk = callService<Fkin>(fkin_, fk_req, opt_.service_timeout_s);
183	  if (!fk || !fk->success) {return -1.0;}
184	  const Vec3 d{fk->conv_posx[0] - pose[0], fk->conv_posx[1] - pose[1], fk->conv_posx[2] - pose[2]};
185	  return norm(d);
186	}
