204	template<class SrvT>
205	typename SrvT::Response::SharedPtr callService(
206	  const typename rclcpp::Client<SrvT>::SharedPtr & client,
207	  const typename SrvT::Request::SharedPtr & request,
208	  double timeout_s)
209	{
210	  if (!client->service_is_ready()) {
211	    return nullptr;
212	  }
213	  auto pending = client->async_send_request(request);
214	  const auto timeout = std::chrono::duration<double>(timeout_s);
215	  if (pending.wait_for(timeout) != std::future_status::ready) {
216	    client->remove_pending_request(pending);  // 늦게 온 응답이 쌓이지 않게 정리
217	    return nullptr;
218	  }
219	  return pending.get();
220	}
