243	GripperResult GripperClient::send(uint8_t command, double force)
244	{
245	  auto req = std::make_shared<GripperCommand::Request>();
246	  req->command = command;
247	  req->force = static_cast<float>(force);
248	  auto res = callService<GripperCommand>(client_, req, timeout_s_);
249	  GripperResult out;
250	  if (!res) {
251	    out.message = std::string(client_->get_service_name()) + " 응답 없음";
252	    return out;
253	  }
254	  out.ok = res->success;
255	  out.holding = res->holding;
256	  out.object_id = res->object_id;
257	  out.message = res->message;
258	  return out;
259	}
