280	TargetEstimator::TargetEstimator(TargetQuery query, double same_object_radius_m)
281	: q_(std::move(query)), same_r_(same_object_radius_m)
282	{
283	  q_.color = lower(q_.color);
284	  q_.shape = lower(q_.shape);
285	}
