351	std::vector<Observation> occupantsNear(
352	  const std::vector<Observation> & objects, const Vec3 & zone_center, double radius,
353	  const Vec3 & target_pos, double same_object_radius)
354	{
355	  std::vector<Observation> out;
356	  for (const auto & o : objects) {
357	    if (normXY(o.position - target_pos) <= same_object_radius) {continue;}   // 목표 자신
358	    if (normXY(o.position - zone_center) <= radius) {out.push_back(o);}
359	  }
360	  return out;
361	}
