376	PickPlacePlan makePickPlacePlan(
377	  const Vec3 & object_base, const Vec3 & zone_surface_base, const GraspGeometry & g)
378	{
379	  const Vec3 up{0.0, 0.0, g.approach_height_m};
380	  PickPlacePlan p;
381	  // 집기: 물체 중심보다 grasp_offset 만큼 위
382	  p.grasp = object_base + Vec3{0.0, 0.0, g.grasp_offset_m};
383	  p.above_object = p.grasp + up;
384	  // 놓기: 물체 중심이 "테이블 + 물체 높이/2 + 여유" 에 오도록, 집을 때와 같은 grasp_offset 유지
385	  p.place = zone_surface_base +
386	    Vec3{0.0, 0.0, g.object_height_m / 2.0 + g.place_clearance_m + g.grasp_offset_m};
387	  p.above_zone = p.place + up;
388	  return p;
389	}
