391	std::string checkWorkspace(const Vec3 & tcp, const Workspace & ws)
392	{
393	  char buf[160];
394	  const double r = normXY(tcp);
395	  if (r < ws.r_min_m || r > ws.r_max_m) {
396	    std::snprintf(buf, sizeof(buf), "수평 거리 %.0f mm 가 허용 범위 [%.0f, %.0f] mm 밖",
397	      r * 1000, ws.r_min_m * 1000, ws.r_max_m * 1000);
398	    return buf;
399	  }
400	  if (tcp.z < ws.z_min_m || tcp.z > ws.z_max_m) {
401	    std::snprintf(buf, sizeof(buf), "높이 %.0f mm 가 허용 범위 [%.0f, %.0f] mm 밖",
402	      tcp.z * 1000, ws.z_min_m * 1000, ws.z_max_m * 1000);
403	    return buf;
404	  }
405	  return "";
406	}
