 80	void RobotClient::waitForMotion(const std::string & label, const AbortCheck & abort)
 81	{
 82	  using clock = std::chrono::steady_clock;
 83	  const auto t0 = clock::now();
 84	  const auto period = std::chrono::duration<double>(opt_.poll_period_s);
 85	  bool seen_moving = false;
 86	  while (true) {
 87	    const ErrorCode why = abort ? abort() : ErrorCode::NONE;
 88	    if (why != ErrorCode::NONE) {
 89	      stop();
 90	      throw TaskError(why, label + ": 이동 중 중단 (" + errorName(why) + ")");
 91	    }
 92	    const double elapsed = std::chrono::duration<double>(clock::now() - t0).count();
 93	    if (elapsed > opt_.motion_timeout_s) {
 94	      stop();
 95	      throw TaskError(ErrorCode::TIMEOUT, label + ": 이동 시간 초과");
 96	    }
 97	    auto res = callService<CheckMotion>(check_motion_, std::make_shared<CheckMotion::Request>(),
 98	        opt_.service_timeout_s);
 99	    if (!res || !res->success) {
100	      stop();
101	      throw TaskError(ErrorCode::MOTION_FAILED, label + ": check_motion 응답 없음");
102	    }
103	    if (res->status != kMotionIdle) {
104	      seen_moving = true;
105	    } else if (seen_moving || elapsed > 0.5) {
106	      // 움직이다 멈췄거나, 0.5 초가 지나도 움직이기 시작하지 않음(이미 그 자리 / 무시된 명령)
107	      return;
108	    }
109	    std::this_thread::sleep_for(period);
110	  }
111	}
