287	bool TargetEstimator::matches(const Observation & o) const
288	{
289	  if (lower(o.color) != q_.color) {return false;}
290	  if (!q_.shape.empty() && lower(o.shape) != q_.shape) {return false;}
291	  return o.confidence >= q_.min_confidence;
292	}
