294	void TargetEstimator::addFrame(const std::vector<Observation> & objects)
295	{
296	  ++seen_;
297	  std::vector<const Observation *> hits;
298	  for (const auto & o : objects) {
299	    if (matches(o)) {hits.push_back(&o);}
300	  }
301	  if (hits.empty()) {return;}
302	
303	  Vec3 mean;
304	  for (auto * h : hits) {mean = mean + h->position;}
305	  mean = mean * (1.0 / static_cast<double>(hits.size()));
306	  for (auto * h : hits) {
307	    if (normXY(h->position - mean) > same_r_) {   // 서로 떨어진 후보가 둘 이상 -> 어느 것인지 모름
308	      ++ambiguous_frames_;
309	      max_candidates_ = std::max(max_candidates_, static_cast<int>(hits.size()));
310	      return;
311	    }
312	  }
313	  samples_.push_back(mean);
314	  if (id_.empty()) {id_ = hits.front()->id;}
315	}
316	
317	Estimate TargetEstimator::estimate(int required_frames, double max_spread_m) const
318	{
319	  Estimate e;
320	  e.frames_seen = seen_;
321	  e.frames_matched = framesMatched();
322	  e.id = id_;
323	  char buf[200];
324	  if (ambiguous_frames_ > 0) {
325	    e.status = EstimateStatus::AMBIGUOUS;
326	    std::snprintf(buf, sizeof(buf), "조건에 맞는 물체가 서로 떨어져 %d개 보임 (영상 %d장) - 어느 것인지 정할 수 없음",
327	      max_candidates_, ambiguous_frames_);
328	    e.reason = buf;
329	    return e;
330	  }
331	  if (e.frames_matched < required_frames) {
332	    e.status = EstimateStatus::NOT_FOUND;
333	    std::snprintf(buf, sizeof(buf), "영상 %d장 중 %d장에서만 보임 (필요 %d장)",
334	      seen_, e.frames_matched, required_frames);
335	    e.reason = buf;
336	    return e;
337	  }
338	  for (const auto & s : samples_) {e.mean = e.mean + s;}
339	  e.mean = e.mean * (1.0 / static_cast<double>(samples_.size()));
340	  for (const auto & s : samples_) {e.spread_m = std::max(e.spread_m, normXY(s - e.mean));}
341	  if (e.spread_m > max_spread_m) {
342	    e.status = EstimateStatus::UNSTABLE;
343	    std::snprintf(buf, sizeof(buf), "위치가 %.1f mm 흔들림 (허용 %.1f mm)", e.spread_m * 1000, max_spread_m * 1000);
344	    e.reason = buf;
345	    return e;
346	  }
347	  e.status = EstimateStatus::OK;
348	  return e;
349	}
