 51	class TaskManagerNode : public rclcpp::Node
 52	{
 53	public:
 54	  using ExecuteTask = aris3_interfaces::action::ExecuteTask;
 55	  using GoalHandle = rclcpp_action::ServerGoalHandle<ExecuteTask>;
 56	
 57	  explicit TaskManagerNode(const rclcpp::NodeOptions & options = rclcpp::NodeOptions());
 58	  ~TaskManagerNode() override;
