 61	  // ---- 작업 하나의 진행 상황을 담는 구조체 (execute() 안에서만 사용)
 62	  struct TaskContext
 63	  {
 64	    std::shared_ptr<GoalHandle> goal_handle;
 65	    ExecuteTask::Goal goal;
 66	    std::string task_id;
