423	void TaskManagerNode::handleAccepted(std::shared_ptr<GoalHandle> goal_handle)
424	{
425	  if (worker_.joinable()) {
426	    worker_.join();  // 이전 작업 스레드는 이미 끝났다 (busy_ 가 false 였으므로)
427	  }
428	  worker_ = std::thread([this, goal_handle]() {execute(goal_handle);});
