293	   293	  auto req = std::make_shared<GetResult::Request>();
294	   294	  for (size_t i = 0; i < req->goal_id.uuid.size(); ++i) {req->goal_id.uuid[i] = static_cast<uint8_t>(0xA5 ^ i);}
295	   295	  auto fut = client->async_send_request(req);
296	   296	  const auto rc = rclcpp::spin_until_future_complete(probe, fut, 1500ms);
297	   297	  RCLCPP_INFO(probe->get_logger(), "중복 확인: %s 이름 있음, 응답 %s", action_name.c_str(),
298	   298	    rc == rclcpp::FutureReturnCode::SUCCESS ? "있음(살아 있는 서버)" : "없음(이전 프로세스의 흔적)");
299	   299	  return rc == rclcpp::FutureReturnCode::SUCCESS;
300	   300	}
