432	   432	// 작업 스레드: 상태 머신 본체
433	   433	// =====================================================================================
434	   434	void TaskManagerNode::execute(std::shared_ptr<GoalHandle> goal_handle)
435	   435	{
436	   436	  TaskContext ctx;
437	   437	  ctx.goal_handle = goal_handle;
438	   438	  ctx.goal = *goal_handle->get_goal();
439	   439	  ctx.start = std::chrono::steady_clock::now();
440	   440	  ctx.task_id = lower(ctx.goal.target_color) + "->" + upper(ctx.goal.destination) + " #" +
441	   441	    std::to_string(++task_counter_);
442	   442	
443	   443	  ErrorCode code = ErrorCode::NONE;
444	   444	  std::string message;
445	   445	  try {
446	   446	    stageValidate(ctx);
447	   447	    stageObserve(ctx);
448	   448	    stagePerceive(ctx);
449	   449	    stagePlan(ctx);
450	   450	    if (ctx.goal.dry_run) {
451	   451	      message = "dry_run: 인식과 계획까지 성공 (로봇은 움직이지 않음). 물체 " + xyz(ctx.object_world);
452	   452	    } else {
453	   453	      // 집기는 실패하면 정해진 횟수만큼 "다시 보고, 다시 계획하고" 재시도한다.
454	   454	      for (ctx.grasp_attempt = 1;; ++ctx.grasp_attempt) {
455	   455	        try {
456	   456	          stagePick(ctx);
457	   457	          break;
458	   458	        } catch (const TaskError & e) {
459	   459	          if (e.code() != ErrorCode::GRASP_FAILED || ctx.grasp_attempt >= max_grasp_attempts_) {
460	   460	            throw;
461	   461	          }
462	   462	          RCLCPP_WARN(get_logger(), "집기 실패 (%d/%d): %s -> 다시 관찰", ctx.grasp_attempt,
463	   463	            max_grasp_attempts_, e.what());
464	   464	          stageObserve(ctx);
465	   465	          stagePerceive(ctx);
466	   466	          stagePlan(ctx);
467	   467	        }
468	   468	      }
469	   469	      stagePlace(ctx);
470	   470	      stageVerify(ctx);
471	   471	      message = fmt("완료: 구역 중심에서 %.1f mm (허용 %.0f mm)", ctx.result->place_error_mm,
472	   472	          zone_tolerance_m_ * 1000, 0);
473	   473	    }
474	   474	  } catch (const TaskError & e) {
475	   475	    code = e.code();
476	   476	    message = e.what();
477	   477	  } catch (const std::exception & e) {
478	   478	    code = ErrorCode::INTERNAL;
479	   479	    message = std::string("예상하지 못한 오류: ") + e.what();
480	   480	  }
481	   481	
482	   482	  auto & r = *ctx.result;
483	   483	  const Stage failed_stage = ctx.stage;
484	   484	  if (code != ErrorCode::NONE) {
485	   485	    RCLCPP_ERROR(get_logger(), "[%s] 실패 %s: %s", stageName(failed_stage), errorName(code), message.c_str());
486	   486	    recover(ctx, code);
487	   487	    if (ctx.holding) {
488	   488	      message += " (물체를 잡은 상태로 끝남)";
489	   489	    }
490	   490	  }
491	   491	  r.success = (code == ErrorCode::NONE);
492	   492	  r.error_code = static_cast<uint8_t>(code);
493	   493	  r.message = message;
494	   494	  r.failed_stage = r.success ? "" : stageName(failed_stage);
495	   495	  r.duration_s = std::chrono::duration<float>(std::chrono::steady_clock::now() - ctx.start).count();
496	   496	
497	   497	  try {
498	   498	    if (code == ErrorCode::CANCELED && goal_handle->is_canceling()) {
499	   499	      goal_handle->canceled(ctx.result);
500	   500	    } else if (r.success) {
501	   501	      goal_handle->succeed(ctx.result);
502	   502	    } else {
503	   503	      goal_handle->abort(ctx.result);
504	   504	    }
505	   505	  } catch (const std::exception & e) {
506	   506	    RCLCPP_ERROR(get_logger(), "결과 전송 실패: %s", e.what());
507	   507	  }
508	   508	  RCLCPP_INFO(get_logger(), "작업 %s 종료: %s (%.1f s) %s", ctx.task_id.c_str(),
509	   509	    r.success ? "성공" : errorName(code), r.duration_s, message.c_str());
510	   510	  publishStatus(r.success ? TaskStatus::STATE_IDLE : TaskStatus::STATE_ERROR, ctx.task_id,
511	   511	    r.success ? "DONE" : stageName(failed_stage), message);
512	   512	  busy_ = false;  // 맨 마지막에 풀어야 다음 요청이 이 작업과 겹치지 않는다
513	   513	}
514	   514	
515	   515	// ---- 1. VALIDATE: 요청 내용과 장비 준비 상태를 움직이기 전에 모두 확인한다.
516	   516	void TaskManagerNode::stageValidate(TaskContext & ctx)
517	   517	{
518	   518	  enterStage(ctx, Stage::VALIDATE, "요청과 장비 준비 상태 확인");
519	   519	  const auto & g = ctx.goal;
520	   520	  if (!g.task_type.empty() && lower(g.task_type) != "pick_place") {
521	   521	    throw TaskError(ErrorCode::INVALID_GOAL, "지원하지 않는 작업 종류: " + g.task_type);
522	   522	  }
523	   523	  const std::string color = lower(g.target_color);
524	   524	  if (std::find(known_colors_.begin(), known_colors_.end(), color) == known_colors_.end()) {
525	   525	    std::string list;
526	   526	    for (const auto & c : known_colors_) {list += c + " ";}
527	   527	    throw TaskError(ErrorCode::INVALID_GOAL, "모르는 색 '" + g.target_color + "' (가능: " + list + ")");
528	   528	  }
529	   529	  auto zone = zones_world_.find(upper(g.destination));
530	   530	  if (zone == zones_world_.end()) {
531	   531	    std::string list;
532	   532	    for (const auto & z : zones_world_) {list += z.first + " ";}
533	   533	    throw TaskError(ErrorCode::INVALID_GOAL, "모르는 구역 '" + g.destination + "' (가능: " + list + ")");
534	   534	  }
535	   535	  ctx.zone_world = zone->second;
536	   536	  ctx.query = TargetQuery{color, lower(g.target_shape), min_confidence_};
537	   537	
538	   538	  std::string missing;
539	   539	  if (!robot_->servicesReady(&missing)) {
540	   540	    throw TaskError(ErrorCode::NOT_READY, "로봇 서비스 없음: " + missing + " (시뮬레이션/로봇 접속 확인)");
541	   541	  }
542	   542	  const int state = robot_->robotState();
543	   543	  if (state != kStandby) {
544	   544	    throw TaskError(ErrorCode::NOT_READY, "로봇이 대기(STANDBY) 상태가 아님 (state=" + std::to_string(state) + ")");
545	   545	  }
546	   546	  if (!gripper_->ready()) {
547	   547	    throw TaskError(ErrorCode::NOT_READY, "그리퍼 서비스 없음: " + gripper_->serviceName());
548	   548	  }
549	   549	  // 이전 작업이 취소되어 물체를 잡은 채 끝났을 수 있다. 그 상태로 새 작업을 시작하면 안 된다.
550	   550	  const auto gs = gripper_->status();
551	   551	  if (!gs.ok) {
552	   552	    throw TaskError(ErrorCode::NOT_READY, "그리퍼 상태 확인 실패: " + gs.message);
553	   553	  }
554	   554	  if (gs.holding) {
555	   555	    throw TaskError(ErrorCode::NOT_READY, "그리퍼가 이미 " + (gs.object_id.empty() ? std::string("물체") : gs.object_id) +
556	   556	            " 를 잡고 있음 - 먼저 정리 (README의 '물체를 잡은 채 멈췄을 때')");
557	   557	  }
558	   558	  {
559	   559	    std::lock_guard<std::mutex> lk(frames_mutex_);
560	   560	    const double age = std::chrono::duration<double>(std::chrono::steady_clock::now() - last_frame_time_).count();
561	   561	    if (frame_seq_ == 0 || age > 2.0) {
562	   562	      throw TaskError(ErrorCode::NOT_READY, "카메라 인식 결과가 들어오지 않음 (" +
563	   563	              get_parameter("detections_topic").as_string() + ")");
564	   564	    }
565	   565	  }
566	   566	  std::string tf_error;
567	   567	  if (!refreshTransforms(&tf_error)) {
568	   568	    throw TaskError(ErrorCode::NOT_READY, "좌표 변환 없음: " + tf_error);
569	   569	  }
570	   570	  report(ctx, "확인 완료: 로봇 대기, 그리퍼·카메라·TF 정상. 구역 " + upper(g.destination) + " " +
571	   571	    xyz(ctx.zone_world), 1.0);
572	   572	}
