574	   574	// ---- 2. OBSERVE: 카메라 시야를 가리지 않는 자세(홈)로 이동.
575	   575	void TaskManagerNode::stageObserve(TaskContext & ctx)
576	   576	{
577	   577	  enterStage(ctx, Stage::OBSERVE, "관찰 자세(홈)로 이동");
578	   578	  if (ctx.goal.dry_run) {
579	   579	    report(ctx, "dry_run: 이동 생략, 현재 자세에서 관찰", 1.0);
580	   580	    return;
581	   581	  }
