587	   587	// ---- 3. PERCEIVE: 여러 장의 카메라 결과로 목표 물체 위치를 정한다.
588	   588	void TaskManagerNode::stagePerceive(TaskContext & ctx)
589	   589	{
590	   590	  enterStage(ctx, Stage::PERCEIVE, "카메라로 " + ctx.query.color + " 물체 찾기");
591	   591	  const Estimate e = perceive(ctx, "집기 전");
592	   592	  switch (e.status) {
593	   593	    case EstimateStatus::OK: break;
594	   594	    case EstimateStatus::NOT_FOUND: throw TaskError(ErrorCode::TARGET_NOT_FOUND, "목표를 못 찾음: " + e.reason);
595	   595	    case EstimateStatus::UNSTABLE: throw TaskError(ErrorCode::TARGET_UNSTABLE, "목표 위치 불안정: " + e.reason);
596	   596	    case EstimateStatus::AMBIGUOUS: throw TaskError(ErrorCode::TARGET_AMBIGUOUS, e.reason);
597	   597	  }
598	   598	  ctx.object_world = e.mean;
599	   599	  ctx.object_id = e.id;
600	   600	  ctx.result->picked_from = toPoint(e.mean);
601	   601	  // 놓을 구역이 비어 있는가? 다른 물체가 있으면 그 위에 쌓거나 부딪힌다.
602	   602	  const auto occupants = occupantsNear(ctx.last_objects, ctx.zone_world, zone_clear_radius_m_, e.mean);
603	   603	  if (!occupants.empty()) {
604	   604	    const auto & o = occupants.front();
605	   605	    throw TaskError(ErrorCode::DESTINATION_OCCUPIED, "구역 " + upper(ctx.goal.destination) + "에 이미 " +
606	   606	            (o.id.empty() ? o.color : o.id) + " 가 있음 " + xyz(o.position) + " - 움직이지 않음");
607	   607	  }
608	   608	  report(ctx, "찾음: " + (e.id.empty() ? ctx.query.color : e.id) + " " + xyz(e.mean) +
609	   609	    fmt(" (영상 %.0f장, 흔들림 %.1f mm)", e.frames_matched, e.spread_m * 1000, 0), 1.0);
610	   610	}
611	   611	
612	   612	Estimate TaskManagerNode::perceive(TaskContext & ctx, const std::string & purpose)
613	   613	{
614	   614	  TargetEstimator est(ctx.query);
615	   615	  uint64_t last_seq;
616	   616	  {
617	   617	    std::lock_guard<std::mutex> lk(frames_mutex_);
618	   618	    last_seq = frame_seq_;  // 지금 이후에 들어오는 영상만 쓴다 (이동 중에 찍힌 영상 제외)
619	   619	  }
620	   620	  const auto deadline = std::chrono::steady_clock::now() + std::chrono::duration<double>(perception_timeout_s_);
621	   621	  while (std::chrono::steady_clock::now() < deadline) {
622	   622	    const ErrorCode why = abortReason(ctx);
623	   623	    if (why != ErrorCode::NONE) {
624	   624	      throw TaskError(why, purpose + " 인식 중 중단");
625	   625	    }
626	   626	    {
627	   627	      std::lock_guard<std::mutex> lk(frames_mutex_);
628	   628	      for (const auto & f : frames_) {
629	   629	        if (f.seq > last_seq) {
630	   630	          est.addFrame(f.objects);
631	   631	          last_seq = f.seq;
632	   632	          ctx.last_objects = f.objects;
633	   633	        }
634	   634	      }
635	   635	    }
636	   636	    if (est.framesMatched() >= perception_frames_ || est.framesSeen() >= 3 * perception_frames_) {
637	   637	      break;
638	   638	    }
639	   639	    std::this_thread::sleep_for(50ms);
640	   640	  }
641	   641	  return est.estimate(perception_frames_, max_spread_m_);
642	   642	}
643	   643	
644	   644	// ---- 4. PLAN: 경로점을 계산하고, 움직이기 전에 모두 갈 수 있는지 확인한다.
645	   645	void TaskManagerNode::stagePlan(TaskContext & ctx)
646	   646	{
647	   647	  enterStage(ctx, Stage::PLAN, "경로점 계산과 도달 가능성 확인");
648	   648	  const Vec3 object_base = worldToBase(ctx.object_world);
649	   649	  const Vec3 zone_base = worldToBase(ctx.zone_world);
650	   650	  ctx.plan = makePickPlacePlan(object_base, zone_base, geom_);
651	   651	  const auto wps = ctx.plan.waypoints();
652	   652	  for (size_t i = 0; i < wps.size(); ++i) {
653	   653	    const auto & wp = wps[i];
654	   654	    const std::string why = checkWorkspace(wp.tcp, workspace_);
655	   655	    if (!why.empty()) {
656	   656	      throw TaskError(ErrorCode::UNREACHABLE, wp.name + " " + xyz(wp.tcp) + ": " + why + " - 움직이지 않음");
657	   657	    }
658	   658	    const double err = robot_->reachabilityErrorMm(flangePoseMmDeg(wp.tcp, geom_, tool_zyz_deg_));
659	   659	    if (err < 0.0) {
660	   660	      throw TaskError(ErrorCode::NOT_READY, "역기구학(ikin/fkin) 서비스 응답 없음");
661	   661	    }
662	   662	    if (err > reach_tolerance_mm_) {
663	   663	      throw TaskError(ErrorCode::UNREACHABLE, wp.name + " " + xyz(wp.tcp) +
664	   664	              fmt(": 로봇이 닿지 않음 (IK->FK 오차 %.1f mm) - 움직이지 않음", err, 0, 0));
665	   665	    }
666	   666	    report(ctx, wp.name + " " + xyz(wp.tcp) + " (base) 확인", (i + 1.0) / wps.size());
667	   667	  }
668	   668	}
669	   669	
670	   670	// ---- 5. PICK: 열기 → 물체 위 → 하강 → 닫기(잡았는지 확인) → 들어 올리기
671	   671	void TaskManagerNode::stagePick(TaskContext & ctx)
672	   672	{
673	   673	  enterStage(ctx, Stage::PICK, "집기 (시도 " + std::to_string(ctx.grasp_attempt) + "/" +
674	   674	    std::to_string(max_grasp_attempts_) + ")");
675	   675	  auto g = gripper_->open();
676	   676	  if (!g.ok) {
677	   677	    throw TaskError(ErrorCode::MOTION_FAILED, "그리퍼 열기 실패: " + g.message);
678	   678	  }
679	   679	  moveTcp(ctx, ctx.plan.above_object, "물체 위로");
680	   680	  moveTcp(ctx, ctx.plan.grasp, "집기 위치로 하강");
681	   681	  report(ctx, "그리퍼 닫기", 0.6);
682	   682	  g = gripper_->close(grip_force_);
683	   683	  const bool wrong_object = !ctx.object_id.empty() && !g.object_id.empty() && g.object_id != ctx.object_id;
684	   684	  if (!g.ok || !g.holding || wrong_object) {
685	   685	    gripper_->open();
686	   686	    moveTcp(ctx, ctx.plan.above_object, "빈손으로 위로");
687	   687	    throw TaskError(ErrorCode::GRASP_FAILED, "잡지 못함: " + g.message +
688	   688	            (wrong_object ? " (다른 물체 " + g.object_id + ")" : ""));
689	   689	  }
690	   690	  ctx.holding = true;
691	   691	  report(ctx, "잡음: " + (g.object_id.empty() ? ctx.query.color : g.object_id), 0.7);
692	   692	  moveTcp(ctx, ctx.plan.above_object, "들어 올리기");
693	   693	}
694	   694	
695	   695	// ---- 6. PLACE: 구역 위 → 하강 → 열기 → 위로 빠지기
696	   696	void TaskManagerNode::stagePlace(TaskContext & ctx)
697	   697	{
698	   698	  enterStage(ctx, Stage::PLACE, "구역 " + upper(ctx.goal.destination) + "에 놓기");
699	   699	  moveTcp(ctx, ctx.plan.above_zone, "구역 위로");
700	   700	  moveTcp(ctx, ctx.plan.place, "놓는 위치로 하강");
701	   701	  auto g = gripper_->open();
702	   702	  if (!g.ok) {
703	   703	    throw TaskError(ErrorCode::MOTION_FAILED, "그리퍼 열기 실패: " + g.message);
704	   704	  }
705	   705	  ctx.holding = false;
706	   706	  report(ctx, "놓음", 0.7);
707	   707	  moveTcp(ctx, ctx.plan.above_zone, "위로 빠지기");
708	   708	}
709	   709	
710	   710	// ---- 7. VERIFY: 홈으로 돌아가 카메라로 물체가 구역 안에 있는지 다시 확인 (닫힌 고리)
711	   711	void TaskManagerNode::stageVerify(TaskContext & ctx)
712	   712	{
713	   713	  enterStage(ctx, Stage::VERIFY, "관찰 자세로 돌아가 카메라로 결과 확인");
714	   714	  robot_->moveJoints(home_deg_, "관찰 자세(홈)", abortCheck(ctx));
715	   715	  sleepChecked(ctx, settle_time_s_);
716	   716	  const Estimate e = perceive(ctx, "놓은 뒤");
717	   717	  if (e.status != EstimateStatus::OK) {
718	   718	    throw TaskError(ErrorCode::PLACE_VERIFY_FAILED, "놓은 뒤 물체를 확인하지 못함: " + e.reason);
719	   719	  }
720	   720	  const double err = normXY(e.mean - ctx.zone_world);
721	   721	  ctx.result->placed_at = toPoint(e.mean);
722	   722	  ctx.result->place_error_mm = static_cast<float>(err * 1000.0);
723	   723	  if (err > zone_tolerance_m_) {
724	   724	    throw TaskError(ErrorCode::PLACE_VERIFY_FAILED,
725	   725	            fmt("구역 밖: 중심에서 %.1f mm (허용 %.0f mm)", err * 1000, zone_tolerance_m_ * 1000, 0));
726	   726	  }
727	   727	  report(ctx, "구역 안 확인: 물체 " + xyz(e.mean) + fmt(", 중심에서 %.1f mm", err * 1000, 0, 0), 1.0);
728	   728	}
729	   729	
730	   730	// ---- 실패·취소 후 처리
731	   731	// 취소: 정지만 한다. 사용자가 "멈춰" 라고 했는데 로봇이 더 움직이면 놀란다.
732	   732	// 실패: 정지 → (낮은 곳에 있으면) 위로 피하기 → 홈. 물체를 잡고 있으면 놓지 않는다(떨어뜨리지 않기).
733	   733	void TaskManagerNode::recover(TaskContext & ctx, ErrorCode cause)
734	   734	{
735	   735	  const Stage failed = ctx.stage;
736	   736	  ctx.stage = Stage::RECOVER;
737	   737	  report(ctx, std::string("정지 (원인 ") + errorName(cause) + ")");
738	   738	  robot_->stop();
739	   739	  if (cause == ErrorCode::CANCELED) {
740	   740	    report(ctx, ctx.holding ? "취소: 정지만 함 (물체는 잡은 채)" : "취소: 정지만 함");
741	   741	    return;
742	   742	  }
743	   743	  const bool arm_may_be_low = (failed == Stage::PICK || failed == Stage::PLACE);
744	   744	  if (!return_home_on_failure_ || !arm_may_be_low || ctx.goal.dry_run) {
745	   745	    return;
746	   746	  }
747	   747	  // 복구 이동에는 취소를 적용하지 않고 이동 시간 초과만 적용한다.
748	   748	  const RobotClient::AbortCheck only_timeout = []() {return ErrorCode::NONE;};
749	   749	  try {
750	   750	    if (auto pose = robot_->currentPose()) {
751	   751	      Vec3 tcp = tcpFromFlangeMm(*pose, geom_);
752	   752	      const double safe_z = std::min(tcp.z + geom_.approach_height_m, workspace_.z_max_m);
753	   753	      if (tcp.z < safe_z - 0.005) {
754	   754	        tcp.z = safe_z;
755	   755	        report(ctx, "복구: 위로 피하기");
756	   756	        robot_->moveLinear(flangePoseMmDeg(tcp, geom_, tool_zyz_deg_), "복구: 위로", only_timeout);
757	   757	      }
758	   758	    }
759	   759	    report(ctx, "복구: 홈으로");
760	   760	    robot_->moveJoints(home_deg_, "복구: 홈", only_timeout);
761	   761	    report(ctx, "복구 완료");
762	   762	  } catch (const TaskError & e) {
763	   763	    RCLCPP_ERROR(get_logger(), "복구 이동 실패: %s (사람이 확인해야 함)", e.what());
764	   764	  }
765	   765	}
766	   766	
767	   767	// =====================================================================================
768	   768	// 도우미
769	   769	// =====================================================================================
770	   770	void TaskManagerNode::moveTcp(TaskContext & ctx, const Vec3 & tcp_base, const std::string & label)
771	   771	{
772	   772	  report(ctx, label + " " + xyz(baseToWorld(tcp_base)) + " (" + world_frame_ + ")",
773	   773	    std::min(0.95, ctx.stage_fraction + 0.15));
774	   774	  robot_->moveLinear(flangePoseMmDeg(tcp_base, geom_, tool_zyz_deg_), label, abortCheck(ctx));
775	   775	}
776	   776	
777	   777	void TaskManagerNode::enterStage(TaskContext & ctx, Stage stage, const std::string & detail)
778	   778	{
779	   779	  ctx.stage = stage;
780	   780	  ctx.stage_fraction = 0.0;
781	   781	  publishStatus(TaskStatus::STATE_BUSY, ctx.task_id, stageName(stage), detail);
782	   782	  report(ctx, detail, 0.0);
783	   783	}
784	   784	
785	   785	void TaskManagerNode::report(TaskContext & ctx, const std::string & detail, double stage_fraction)
786	   786	{
787	   787	  auto fb = std::make_shared<ExecuteTask::Feedback>();
788	   788	  const int index = std::min(static_cast<int>(ctx.stage), kMainStageCount);
789	   789	  fb->stage = stageName(ctx.stage);
790	   790	  fb->stage_index = static_cast<uint8_t>(index);
791	   791	  fb->stage_count = kMainStageCount;
792	   792	  fb->detail = detail;
793	   793	  if (stage_fraction >= 0.0) {  // 음수 = 진행률은 그대로 두고 설명만 보냄
794	   794	    ctx.stage_fraction = std::max(ctx.stage_fraction, std::min(1.0, stage_fraction));
795	   795	  }
796	   796	  fb->progress = static_cast<float>(std::min(1.0, (index + ctx.stage_fraction) / kMainStageCount));
797	   797	  RCLCPP_INFO(get_logger(), "[%s] %s", fb->stage.c_str(), detail.c_str());
798	   798	  try {
799	   799	    if (ctx.goal_handle->is_active()) {
800	   800	      ctx.goal_handle->publish_feedback(fb);
801	   801	    }
802	   802	  } catch (const std::exception &) {
803	   803	    // 결과를 이미 보낸 뒤라면 feedback 은 보낼 수 없다 — 무시
804	   804	  }
805	   805	}
806	   806	
807	   807	ErrorCode TaskManagerNode::abortReason(const TaskContext & ctx) const
808	   808	{
809	   809	  if (!rclcpp::ok()) {return ErrorCode::CANCELED;}
810	   810	  if (ctx.goal_handle->is_canceling()) {return ErrorCode::CANCELED;}
811	   811	  const double elapsed = std::chrono::duration<double>(std::chrono::steady_clock::now() - ctx.start).count();
812	   812	  if (elapsed > task_timeout_s_) {return ErrorCode::TIMEOUT;}
813	   813	  return ErrorCode::NONE;
814	   814	}
815	   815	
816	   816	RobotClient::AbortCheck TaskManagerNode::abortCheck(const TaskContext & ctx) const
817	   817	{
818	   818	  return [this, &ctx]() {return abortReason(ctx);};
819	   819	}
820	   820	
821	   821	void TaskManagerNode::sleepChecked(TaskContext & ctx, double seconds)
822	   822	{
823	   823	  const auto end = std::chrono::steady_clock::now() + std::chrono::duration<double>(seconds);
824	   824	  while (std::chrono::steady_clock::now() < end) {
825	   825	    const ErrorCode why = abortReason(ctx);
826	   826	    if (why != ErrorCode::NONE) {
827	   827	      throw TaskError(why, "대기 중 중단");
828	   828	    }
829	   829	    std::this_thread::sleep_for(50ms);
830	   830	  }
831	   831	}
832	   832	
833	   833	// ---- TF2: world <-> base_link
834	   834	bool TaskManagerNode::refreshTransforms(std::string * error)
835	   835	{
836	   836	  for (int i = 0; i < 20; ++i) {   // 최대 2 초 기다린다 (TF 는 별도 스레드가 채워 준다)
837	   837	    try {
838	   838	      T_base_world_ = tf_buffer_->lookupTransform(base_frame_, world_frame_, tf2::TimePointZero);
839	   839	      T_world_base_ = tf_buffer_->lookupTransform(world_frame_, base_frame_, tf2::TimePointZero);
840	   840	      return true;
841	   841	    } catch (const tf2::TransformException & e) {
842	   842	      if (error) {*error = e.what();}
843	   843	      std::this_thread::sleep_for(100ms);
844	   844	    }
845	   845	  }
846	   846	  return false;
847	   847	}
848	   848	
849	   849	Vec3 TaskManagerNode::worldToBase(const Vec3 & p) const
850	   850	{
851	   851	  geometry_msgs::msg::PointStamped in, out;
852	   852	  in.point = toPoint(p);
853	   853	  tf2::doTransform(in, out, T_base_world_);
854	   854	  return {out.point.x, out.point.y, out.point.z};
855	   855	}
856	   856	
857	   857	Vec3 TaskManagerNode::baseToWorld(const Vec3 & p) const
858	   858	{
859	   859	  geometry_msgs::msg::PointStamped in, out;
860	   860	  in.point = toPoint(p);
861	   861	  tf2::doTransform(in, out, T_world_base_);
862	   862	  return {out.point.x, out.point.y, out.point.z};
863	   863	}
864	   864	
865	   865	// ---- 카메라 결과 받기 (구독 콜백: 짧게 처리하고 버퍼에 넣기만 한다)
866	   866	void TaskManagerNode::onDetections(const DetectedObjectArray::SharedPtr msg)
867	   867	{
868	   868	  std::vector<Observation> objs;
869	   869	  objs.reserve(msg->objects.size());
870	   870	  for (const auto & o : msg->objects) {
871	   871	    const std::string frame = o.pose.header.frame_id.empty() ? msg->header.frame_id : o.pose.header.frame_id;
872	   872	    Vec3 p{o.pose.pose.position.x, o.pose.pose.position.y, o.pose.pose.position.z};
873	   873	    if (frame != world_frame_) {
874	   874	      try {
875	   875	        geometry_msgs::msg::PointStamped in, out;
876	   876	        in.header.frame_id = frame;
877	   877	        in.point = o.pose.pose.position;
878	   878	        out = tf_buffer_->transform(in, world_frame_);
879	   879	        p = {out.point.x, out.point.y, out.point.z};
880	   880	      } catch (const tf2::TransformException & e) {
881	   881	        RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000, "검출 좌표 변환 실패 (%s -> %s): %s",
882	   882	          frame.c_str(), world_frame_.c_str(), e.what());
883	   883	        continue;
884	   884	      }
885	   885	    }
886	   886	    objs.push_back(Observation{o.id, o.color, o.shape, p, o.confidence});
887	   887	  }
888	   888	  std::lock_guard<std::mutex> lk(frames_mutex_);
889	   889	  frames_.push_back(Frame{++frame_seq_, std::move(objs)});
890	   890	  while (frames_.size() > kMaxBufferedFrames) {frames_.pop_front();}
891	   891	  last_frame_time_ = std::chrono::steady_clock::now();
892	   892	}
893	   893	
894	   894	// ---- 상태 토픽
895	   895	void TaskManagerNode::publishStatus(
896	   896	  uint8_t state, const std::string & task_id, const std::string & stage, const std::string & message)
897	   897	{
898	   898	  std::lock_guard<std::mutex> lk(status_mutex_);
899	   899	  last_status_.state = state;
900	   900	  last_status_.task_id = task_id;
901	   901	  last_status_.stage = stage;
902	   902	  last_status_.message = message;
903	   903	  last_status_.stamp = now();
904	   904	  status_pub_->publish(last_status_);
905	   905	}
