907	   907	void TaskManagerNode::onStatusTimer()
908	   908	{
909	   909	  std::lock_guard<std::mutex> lk(status_mutex_);
910	   910	  last_status_.stamp = now();
911	   911	  status_pub_->publish(last_status_);
912	   912	}
