 46	#include "aris3_task_manager/types.hpp"
 47	
 48	namespace aris3_task_manager
 49	{
 50	
 51	class TaskManagerNode : public rclcpp::Node
 52	{
 53	public:
 54	  using ExecuteTask = aris3_interfaces::action::ExecuteTask;
 55	  using GoalHandle = rclcpp_action::ServerGoalHandle<ExecuteTask>;
 56	
 57	  explicit TaskManagerNode(const rclcpp::NodeOptions & options = rclcpp::NodeOptions());
 58	  ~TaskManagerNode() override;
 59	
 60	private:
 61	  // ---- 작업 하나의 진행 상황을 담는 구조체 (execute() 안에서만 사용)
 62	  struct TaskContext
 63	  {
 64	    std::shared_ptr<GoalHandle> goal_handle;
 65	    ExecuteTask::Goal goal;
 66	    std::string task_id;
 67	    std::chrono::steady_clock::time_point start;
 68	    Stage stage{Stage::VALIDATE};
 69	    double stage_fraction{0.0};   // 현재 단계 안에서의 진행 (0~1, 줄어들지 않음)
 70	    TargetQuery query;
 71	    Vec3 zone_world;              // 구역 중심의 테이블 표면 점 (world)
 72	    Vec3 object_world;            // 카메라가 본 물체 중심 (world)
 73	    std::string object_id;
 74	    std::vector<Observation> last_objects;  // 마지막으로 받은 영상의 모든 물체 (구역 점유 확인용)
 75	    PickPlacePlan plan;           // base frame
 76	    bool holding{false};
 77	    int grasp_attempt{0};
 78	    std::shared_ptr<ExecuteTask::Result> result{std::make_shared<ExecuteTask::Result>()};
 79	  };
 80	
 81	  // ---- 액션 서버 콜백 (executor 스레드, 빨리 끝나야 함)
 82	  rclcpp_action::GoalResponse handleGoal(
 83	    const rclcpp_action::GoalUUID & uuid, std::shared_ptr<const ExecuteTask::Goal> goal);
 84	  rclcpp_action::CancelResponse handleCancel(std::shared_ptr<GoalHandle> goal_handle);
 85	  void handleAccepted(std::shared_ptr<GoalHandle> goal_handle);
 86	
 87	  // ---- 작업 스레드
 88	  void execute(std::shared_ptr<GoalHandle> goal_handle);
 89	  void stageValidate(TaskContext & ctx);
 90	  void stageObserve(TaskContext & ctx);
 91	  void stagePerceive(TaskContext & ctx);
 92	  void stagePlan(TaskContext & ctx);
 93	  void stagePick(TaskContext & ctx);
 94	  void stagePlace(TaskContext & ctx);
 95	  void stageVerify(TaskContext & ctx);
 96	  void recover(TaskContext & ctx, ErrorCode cause);
 97	
 98	  Estimate perceive(TaskContext & ctx, const std::string & purpose);
 99	  void moveTcp(TaskContext & ctx, const Vec3 & tcp_base, const std::string & label);
