402	rclcpp_action::GoalResponse TaskManagerNode::handleGoal(
403	  const rclcpp_action::GoalUUID &, std::shared_ptr<const ExecuteTask::Goal> goal)
404	{
405	  // 한 번에 한 작업만. exchange(true) 는 "이전 값을 돌려주고 true 로 바꾸기"를 한 번에(원자적으로) 한다.
406	  if (busy_.exchange(true)) {
407	    RCLCPP_WARN(get_logger(), "거절: 이미 작업 중 (%s -> %s 요청)",
408	      goal->target_color.c_str(), goal->destination.c_str());
409	    return rclcpp_action::GoalResponse::REJECT;
410	  }
411	  RCLCPP_INFO(get_logger(), "수락: %s%s%s -> %s%s", goal->target_color.c_str(),
412	    goal->target_shape.empty() ? "" : " ", goal->target_shape.c_str(), goal->destination.c_str(),
413	    goal->dry_run ? " (dry_run)" : "");
414	  return rclcpp_action::GoalResponse::ACCEPT_AND_EXECUTE;
415	}
